public class TilePanel:Panel {
 public double TileWidth=270,TileHeight=96; public ScrollViewer Host; public double DragWidth;
 bool VisibleAt(int i,int columns){if(Host==null||Host.ViewportHeight<=0)return true;double y=(i/columns)*TileHeight;return y+TileHeight>=Host.VerticalOffset-TileHeight&&y<=Host.VerticalOffset+Host.ViewportHeight+TileHeight;}
 protected override Size MeasureOverride(Size size){double w=DragWidth>0?DragWidth:Double.IsInfinity(size.Width)?TileWidth:size.Width;int n=Math.Max(1,(int)(w/TileWidth));double cell=w/n;for(int i=0;i<Children.Count;i++){var child=Children[i];bool visible=VisibleAt(i,n);var visibility=visible?Visibility.Visible:Visibility.Collapsed;if(child.Visibility!=visibility)child.Visibility=visibility;if(visible)child.Measure(new Size(cell,TileHeight));}return new Size(Double.IsInfinity(size.Width)?w:size.Width,Math.Ceiling((double)Children.Count/n)*TileHeight);}
 protected override Size ArrangeOverride(Size size){double layoutWidth=DragWidth>0?DragWidth:size.Width;int n=Math.Max(1,(int)(layoutWidth/TileWidth));double w=layoutWidth/n;for(int i=0;i<Children.Count;i++)if(Children[i].Visibility==Visibility.Visible)Children[i].Arrange(new Rect(i%n*w,i/n*TileHeight,w,TileHeight));return size;}
}
