 void ExportProgress(List<Achievement> previous,List<Achievement> next){
  exportAdvanced=false;if(previous.Count==0)return;
  foreach(var a in next){var before=previous.FirstOrDefault(x=>x.Key==a.Key);if(before==null)continue;
   bool increased=(!before.Complete&&a.Complete)||a.Progress>before.Progress;
   if(!increased)increased=a.Requirements.Any(r=>r.Current.HasValue&&before.Requirements.Any(old=>old.Text.Split('\t')[0]==r.Text.Split('\t')[0]&&old.Current.HasValue&&r.Current>old.Current));
   if(increased){exportAdvanced=true;recentStamps[a.Key]=++recentSequence;highlighted.Add(a.Key);}
  }
 }
