  var panel=new TilePanel();for(int i=0;i<12;i++)panel.Children.Add(new Border());panel.Measure(new Size(300,Double.PositiveInfinity));panel.Arrange(new Rect(0,0,300,1152));if(panel.Children[1].TranslatePoint(new Point(),panel).X!=0)throw new Exception("Narrow tile layout not single column");panel.Measure(new Size(900,Double.PositiveInfinity));panel.Arrange(new Rect(0,0,900,384));if(panel.Children[1].TranslatePoint(new Point(),panel).Y!=0||panel.Children[3].TranslatePoint(new Point(),panel).Y!=96)throw new Exception("Wide tile layout not wrapping");
 }
 public void CheckTileToggle(){
  ShrinkDetails();Width=340;UpdateLayout();var row=filtered.First();
  SelectTrackerTile(row);if(!detailsOpen||editing!=row)throw new Exception("Tile did not open");
  SelectTrackerTile(row);if(detailsOpen||editing!=null||Math.Abs(Width-340)>1)throw new Exception("Tile did not deselect and shrink");
 }
 void SelectTrackerTile(Row r){
  if(editing==r&&detailsOpen){
   if(!ResolveEdits())return;
   binding=true;grid.UnselectAllCells();grid.SelectedItem=null;binding=false;
   Edit(null);ShrinkDetails();RenderTiles(false);return;
  }
  if(editing!=r&&!ResolveEdits())return;
  Edit(r);binding=true;grid.SelectedItem=r;binding=false;OpenDetails();RenderTiles(false);
 }
